-- Node: mal-severe-treatment (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Severe Malaria — IV Artesunate","body":"**Severe malaria: start IV artesunate promptly.** Parasitemia ≥5% alone qualifies under CDC guidance, regardless of species or other severity findings. [4]\n\n**Emergency acquisition:**\nFDA-approved and commercially available. Hospital pharmacy should urgently contact its distributor or Amivas (855-526-4827, 24/7); obtain stock from a nearby hospital or arrange transfer if faster. CDC provides clinical consultation, not drug supply. [4]\n\n**Initial regimen:**\n• **2.4 mg/kg IV using actual body weight at 0, 12, and 24 hours**, for adults and children of all weights, including pregnancy.\n• Known allergy to IV artemisinins is a contraindication; obtain urgent specialist advice.\n• [Artesunate Dosing Calculator](#/calculator/artesunate-dosing) [4]\n\n**After the third dose:**\nAfter dose 3, obtain a thin smear at least 4 hours later. Continue 2.4 mg/kg IV every 24 hours if parasitemia >1% OR oral medication is not tolerated, for a maximum of 7 total days of IV therapy. Reassess parasitemia daily. [4]\n\n**Full oral follow-on course:**\nOnce parasitemia is ≤1% AND oral medication is tolerated, start a full oral regimen 8-24 hours after the last IV dose, even after 7 days of IV therapy. For P. falciparum, [artemether-lumefantrine follow-on regimen](#/drug/artemether-lumefantrine/follow-on) requires 5 days (10 doses) under CDC August 2026 guidance; atovaquone-proguanil is an alternative 3-day regimen. [4][19]\n\n**If IV artesunate is delayed:**\nWhile obtaining IV artesunate, give interim oral artemether-lumefantrine (preferred); alternatives include atovaquone-proguanil or quinine, with mefloquine reserved for no other options. Consider an antiemetic or nasogastric administration when appropriate. Stop the interim drug and begin IV artesunate immediately when available.\n\nDo not use doxycycline, tetracycline, or clindamycin alone for severe malaria or as interim treatment: parasite clearance is too slow. Their role as a partner with quinine in a complete follow-on regimen is different. [4]\n\n**Avoid exchange transfusion:**\nDo not use exchange transfusion as an adjunct. It has no demonstrated benefit, and IV artesunate rapidly reduces parasite burden. [4]\n\n**Monitoring:**\n• ICU care; infectious disease consultation.\n• Glucose q4-6h; monitor renal function, acidosis, anemia, shock and respiratory status.\n• Blood smears at least daily while hospitalized until no asexual parasites are detected.\n• CBC weekly for 4 weeks from treatment initiation; if abnormal, check reticulocytes, haptoglobin, LDH, bilirubin and a repeat smear for delayed hemolysis. [4]\n\n**CDC consultation:** 770-488-7788 (weekdays 9am-5pm ET), 770-488-7100 (after hours/weekends). [6]","citation":[4,6,19],"next":"mal-complications","treatment":{"firstLine":{"drug":"IV Artesunate","dose":"2.4 mg/kg","route":"IV","frequency":"at 0, 12, 24h, then daily","duration":"Maximum 7 total IV days; then a full oral regimen","notes":"FDA-approved and commercially available. Hospital pharmacy should urgently contact its distributor or Amivas (855-526-4827, 24/7); obtain stock from a nearby hospital or arrange transfer if faster. CDC provides clinical consultation, not drug supply. After dose 3, obtain a thin smear at least 4 hours later. Continue 2.4 mg/kg IV every 24 hours if parasitemia >1% OR oral medication is not tolerated, for a maximum of 7 total days of IV therapy. Reassess parasitemia daily."},"alternative":{"drug":"Oral artemether-lumefantrine (interim bridge)","dose":"Weight-based ACT dosing","route":"PO","frequency":"Use CDC species/weight regimen; stop when IV artesunate arrives","duration":"until IV artesunate arrives","notes":"Do not use doxycycline, tetracycline, or clindamycin alone for severe malaria or as interim treatment: parasite clearance is too slow. Their role as a partner with quinine in a complete follow-on regimen is different."},"monitoring":"ICU monitoring. Glucose q4-6h. Repeat blood smears q12-24h. Monitor for delayed hemolysis (CBC weekly for 4 weeks from treatment initiation)."},"calculatorLinks":[{"id":"artesunate-dosing","label":"Artesunate Dosing"}],"summary":"IV artesunate: commercial emergency procurement, daily reassessment after dose 3, maximum 7 total IV days","safetyLevel":"critical"}'::jsonb
WHERE id = 'mal-severe-treatment' AND tree_id = 'malaria';

-- Node: mal-pregnancy (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Malaria in Pregnancy","body":"**Malaria in pregnancy is life-threatening** to both mother and fetus. Higher risk of severe disease, hypoglycemia, pulmonary edema, and maternal death. [15][16]\n\n[Pregnancy Management Guide](#/info/mal-pregnancy)\n\n**Risk to fetus:** [15][16]\n• Spontaneous abortion, stillbirth\n• Preterm delivery\n• Low birth weight\n• Congenital malaria (rare)\n\n**Treatment by trimester:** [6][15][16]\n\n**First trimester:**\n• **Severe malaria:** IV artesunate (benefits outweigh risks) [6][16]\n• **Uncomplicated *P. falciparum*:** Quinine + clindamycin × 7 days [6][16]\n• **Avoid:** Artemisinin derivatives if possible (teratogenic in animal studies), primaquine (hemolysis risk to fetus), atovaquone-proguanil, doxycycline\n\n**Second and third trimester:**\n• **Severe malaria:** IV artesunate [6][16]\n• **Uncomplicated *P. falciparum*:** Artemether-lumefantrine, quinine + clindamycin, or mefloquine [6][16]\n• **Uncomplicated *P. vivax/ovale*:** Chloroquine for blood stage, **defer primaquine until after delivery** [9][16]\n• Provide chloroquine prophylaxis 300 mg base weekly to suppress relapses until primaquine can be given postpartum [9]\n\n**Monitoring:** [15][16]\n• Glucose q4-6h (hypoglycemia risk higher in pregnancy)\n• Fetal monitoring when feasible\n• Admit all pregnant patients with malaria\n• Obstetrics consultation","citation":[4,6,9,15,16],"next":"mal-disposition","treatment":{"firstLine":{"drug":"IV Artesunate (if severe, any trimester)","dose":"2.4 mg/kg","route":"IV","frequency":"at 0, 12, 24h, then daily","duration":"After dose 3: daily if >1% parasitemia or unable PO; maximum 7 total IV days","notes":"Use in all trimesters. Obtain commercially through hospital pharmacy; CDC provides consultation."},"alternative":{"drug":"Quinine + Clindamycin (1st trimester uncomplicated)","dose":"Quinine 650 mg TID, Clindamycin 20 mg/kg/day divided","route":"PO","frequency":"Quinine TID, Clindamycin TID","duration":"7 days","notes":"Safest option for 1st trimester uncomplicated. ACT preferred after 1st trimester."},"monitoring":"Glucose q4-6h. Fetal monitoring. Admit all pregnant patients. Defer primaquine until postpartum."},"summary":"Severe malaria in pregnancy: IV artesunate (all trimesters). Uncomplicated: quinine + clindamycin 1st trimester","skippable":true,"safetyLevel":"warning"}'::jsonb
WHERE id = 'mal-pregnancy' AND tree_id = 'malaria';

-- Node: mal-pediatric (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Pediatric Malaria Management","body":"**Pediatric patients have higher risk** of severe malaria, hypoglycemia, seizures, and severe anemia. [17]\n\n**Treatment principles:** [6][17]\n• Same species-specific regimens as adults, adjusted for weight\n• Children <5 years have highest mortality from *P. falciparum*\n• Admit all children <5 years with *P. falciparum*\n\n**Severe malaria:** [6][8][17]\n• **IV Artesunate (CDC):** 2.4 mg/kg actual body weight IV at 0, 12, 24h for all pediatric weights, including <20 kg. After dose 3, obtain a thin smear at least 4 hours later. Continue 2.4 mg/kg IV every 24 hours if parasitemia >1% OR oral medication is not tolerated, for a maximum of 7 total days of IV therapy. Reassess parasitemia daily. [4]\n• Obtain FDA-approved IV artesunate commercially through hospital pharmacy [4]\n• ICU admission, close glucose monitoring\n\n**Uncomplicated *P. falciparum*:** [6][17]\n• **Artemether-lumefantrine:** Weight-based dosing (see pediatric dosing table) [10]\n  - 5-14 kg: 1 tablet BID × 3d\n  - 15-24 kg: 2 tablets BID × 3d\n  - 25-34 kg: 3 tablets BID × 3d\n  - ≥35 kg: 4 tablets BID × 3d (adult dose)\n• **Atovaquone-proguanil:** [11]\n  - 5-8 kg: 2 pediatric tablets daily × 3d\n  - 9-10 kg: 3 pediatric tablets daily × 3d\n  - 11-20 kg: 1 adult tablet daily × 3d\n  - >20 kg: adult dosing\n\n**Uncomplicated *P. vivax/ovale*:** [6][9][17]\n• Chloroquine: 10 mg base/kg (max 600 mg base), then 5 mg base/kg at 6, 24, 48h\n• Primaquine (if G6PD normal): 0.5 mg/kg base daily × 14 days [9]\n• **Infants <6 months:** defer primaquine, use chloroquine prophylaxis [9]\n\n**Monitoring:** [17]\n• Glucose q4-6h (hypoglycemia common)\n• Repeat smears day 3, 7\n• Admit <5 years with falciparum, any age with severe malaria","citation":[4,6,8,9,10,11,17],"next":"mal-disposition","treatment":{"firstLine":{"drug":"IV Artesunate (severe)","dose":"2.4 mg/kg actual body weight","route":"IV","frequency":"at 0, 12, 24h, then daily","duration":"After dose 3: daily if >1% parasitemia or unable PO; maximum 7 total IV days","notes":"CDC dosing is 2.4 mg/kg at all weights. Commercial supply through hospital pharmacy. ICU admission."},"alternative":{"drug":"Artemether-Lumefantrine (uncomplicated)","dose":"Weight-based (see dosing table)","route":"PO","frequency":"BID","duration":"3 days","notes":"Take with fatty food. Admit <5 years with falciparum."},"monitoring":"Glucose q4-6h. Admit <5 years with P. falciparum. Repeat smears day 3, 7."},"summary":"Pediatric malaria: same drugs, weight-based dosing — children decompensate faster than adults","skippable":true,"safetyLevel":"warning"}'::jsonb
WHERE id = 'mal-pediatric' AND tree_id = 'malaria';

-- Node: mal-dispo-icu (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"ICU Admission","body":"**ICU admission for severe malaria, including parasitemia ≥5% alone.** [4]\n\n**Treatment and acquisition:**\nFDA-approved and commercially available. Hospital pharmacy should urgently contact its distributor or Amivas (855-526-4827, 24/7); obtain stock from a nearby hospital or arrange transfer if faster. CDC provides clinical consultation, not drug supply.\n\n[IV artesunate](#/drug/iv-artesunate/severe malaria): 2.4 mg/kg IV at 0, 12, and 24h for all ages. After dose 3, obtain a thin smear at least 4 hours later. Continue 2.4 mg/kg IV every 24 hours if parasitemia >1% OR oral medication is not tolerated, for a maximum of 7 total days of IV therapy. Reassess parasitemia daily. [4]\n\n**Oral transition:**\nOnce parasitemia is ≤1% AND oral medication is tolerated, start a full oral regimen 8-24 hours after the last IV dose, even after 7 days of IV therapy. For P. falciparum, [artemether-lumefantrine follow-on regimen](#/drug/artemether-lumefantrine/follow-on) requires 5 days (10 doses) under CDC August 2026 guidance; atovaquone-proguanil is an alternative 3-day regimen. [4][19]\n\n**If IV treatment is delayed:**\nWhile obtaining IV artesunate, give interim oral artemether-lumefantrine (preferred); alternatives include atovaquone-proguanil or quinine, with mefloquine reserved for no other options. Consider an antiemetic or nasogastric administration when appropriate. Stop the interim drug and begin IV artesunate immediately when available.\n\nDo not use doxycycline, tetracycline, or clindamycin alone for severe malaria or as interim treatment: parasite clearance is too slow. Their role as a partner with quinine in a complete follow-on regimen is different. [4]\n\n**Exchange transfusion:**\nDo not use exchange transfusion as an adjunct. It has no demonstrated benefit, and IV artesunate rapidly reduces parasite burden. [4]\n\n**Monitoring and consultation:**\n• Hemodynamic, respiratory, renal and glucose monitoring; treat complications.\n• Thick/thin smears at least daily while hospitalized until negative.\n• Infectious disease and critical care; nephrology if dialysis indicated.\n• Monitor CBC weekly for 4 weeks from treatment initiation for delayed hemolysis; obtain reticulocytes, LDH, haptoglobin, bilirubin and repeat smear if abnormal. [4]","citation":[4,6,19],"recommendation":"ICU admission; commercial IV artesunate. After dose 3, continue daily if parasitemia >1% or unable PO, maximum 7 total days. Full oral follow-on required. No exchange transfusion.","confidence":"definitive","summary":"ICU for severe malaria: IV artesunate for parasitemia ≥5% or another severe criterion, serial smears"}'::jsonb
WHERE id = 'mal-dispo-icu' AND tree_id = 'malaria';

